# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_ДГ5_646_1", r"$a_{n}=2\frac34+(n-1)\cdot\frac25=14\frac34\Rightarrow n-1=\frac{12}{0{,}4}=30$, $n=31$ — число является членом прогрессии; в ключе стояло «нет»",
  k=r"да, это $31$-й член",
  dnew={0: (r"нет", r"Ученик неверно прочитал условие (как степень $2^{3/4}$ или перепутал шаг), получил дробное значение $n$; на самом деле $\frac{14\frac34-2\frac34}{\frac25}=30$, $n=31$.")},
  dadd=[(r"да, это $30$-й член", r"Ученик нашёл $n-1=30$ и записал $n=30$, забыв прибавить $1$: $a_{31}=2\frac34+30\cdot\frac25=14\frac34$.")])
E("G9_TB_ДГ5_646_2", r"в условии разорвана десятичная запятая: «$8$, $35$» вместо $8{,}35$ ($n-1=\frac{8{,}35-2}{0{,}4}=15{,}875$ — не целое, числа в прогрессии нет); ключ «нет» верен",
  q=r"Дана арифметическая прогрессия, первый член которой равен $\dfrac{2^{3}}{4}$, а разность равна $\dfrac{2}{5}$. Является ли членом этой прогрессии число $8{,}35$?")
E("G9_TB_ДГ5_647_1", r"в условии потеряна целая часть: прогрессия $-10\frac12;\ -10\frac14;\ -10;\ \ldots$ ($d=\frac14$), первый положительный член $-10{,}5+0{,}25(n-1)>0\Rightarrow n=44$, $a_{44}=0{,}25$; ключ верен",
  q=r"Найдите первый положительный член арифметической прогрессии $-10\dfrac{1}{2}$; $-10\dfrac{1}{4}$; $-10$; $\ldots$")
E("G9_TB_ДГ5_658_2", r"числа от $51$ до $149$: $\frac{51+149}{2}\cdot99=9900$; кратные $5$ (от $55$ до $145$, $19$ чисел): $\frac{55+145}{2}\cdot19=1900$; $9900-1900=8000$ (в ключе $7920$, верный ответ был дистрактором)",
  k=r"$8000$",
  dnew={0: (r"$7920$", r"Ученик верно нашёл сумму всех чисел ($9900$), но при вычислении суммы кратных $5$ ошибся и получил $1980$ вместо $1900$."),
        1: (r"$9900$", r"Ученик нашёл сумму всех натуральных чисел от $51$ до $149$ и не вычел числа, кратные $5$.")})
E("G9_TB_ДГ5_673", r"$b_{9}=b_{1}q^{8}\Rightarrow q^{8}=\frac{5/3}{135}=\frac1{81}$, $q=\pm\frac1{\sqrt3}$ (а не $\frac13$: при $q=\frac13$ девятый член равнялся бы $\frac{135}{3^{8}}$); при $q=\frac1{\sqrt3}$ члены $b_{2},\dots,b_{8}$: $45\sqrt3;\ 45;\ 15\sqrt3;\ 15;\ 5\sqrt3;\ 5;\ \frac{5\sqrt3}{3}$; при $q=-\frac1{\sqrt3}$ — те же модули с чередующимися знаками. Ключ $45,15,5,\frac53,\dots$ содержал $\frac53$ уже пятым членом",
  k=r"при $q=\dfrac{1}{\sqrt{3}}$: $45\sqrt{3};\ 45;\ 15\sqrt{3};\ 15;\ 5\sqrt{3};\ 5;\ \dfrac{5\sqrt{3}}{3}$ (при $q=-\dfrac{1}{\sqrt{3}}$ — те же по модулю числа со знаками $-,+,-,+,-,+,-$)")
